<script context="module"></script>

<script>
	import * as pluginModule from '@kitschpatrol/tweakpane-plugin-essentials'
	import { BROWSER } from 'esm-env'
	import { createEventDispatcher, onDestroy, onMount } from 'svelte'
	import Blade from '../core/Blade.svelte'
	import ClsPad from '../internal/ClsPad.svelte'
	import { fillWith } from '../utils.js'
	export let rows = void 0
	export let interval = void 0
	export let max = void 0
	export let min = void 0
	export let label = void 0
	let implicitMode = true
	export function begin() {
		implicitMode = false
		ref?.begin()
	}
	export function end() {
		implicitMode = false
		ref?.end()
	}
	let ref
	let requestId
	const dispatch = createEventDispatcher()
	onMount(() => {
		startInternalLoop()
	})
	onDestroy(() => {
		stopInternalLoop()
	})
	function startInternalLoop() {
		loop()
	}
	function loop() {
		ref?.end()
		ref?.begin()
		requestId = requestAnimationFrame(loop)
	}
	function stopInternalLoop() {
		requestId !== void 0 && cancelAnimationFrame(requestId)
	}
	function addListeners() {
		ref.on('tick', () => {
			if (ref.fps !== null) {
				dispatch('change', ref.fps)
			}
		})
	}
	let options
	$: options = {
		interval,
		label,
		max,
		min,
		rows,
		view: 'fpsgraph',
	}
	$: ref !== void 0 && addListeners()
	$: !implicitMode && stopInternalLoop()
</script>

<Blade {options} plugin={pluginModule} bind:ref {...$$restProps} />
{#if !BROWSER}
	{#if rows}
		<ClsPad keysAdd={fillWith('containerUnitSize', rows)} theme={$$props.theme} />
	{:else}
		<ClsPad keysAdd={fillWith('containerUnitSize', 2)} theme={$$props.theme} />
	{/if}
{/if}
